function TakeoutOrderCellNode:GetCostNumTxt(costId, costM, costNum)
    local haveNum = GoodsUtils.GetThingNo(costId)
    local signCount = math.ceil(checkNumber(self.leftTime) / tonumber(costM))
    local needNum = signCount * tonumber(costNum)
    local text = string.format("<color=#fb4a4b>%s</color>/%s", haveNum, needNum)
    if haveNum >= needNum then
        text = string.format("<color=#FFFFFF>%s</color>/%s", haveNum, needNum)
    end
    return text
end
---OnTimeTick
---@param orderId number 订单Id
---@param text number/string 根据不同情况 会有不同的值
function TakeoutOrderCellNode:OnTimeTick(orderId, text)
    --正在配送<size=50><color=#d7184a>2:20:00</color></size>
    if self.data and checkNumber(self.data.id) == checkNumber(orderId) then
        if self.data.status == Status.Cold then
            self.leftTime = text
            CfUtils.FillText(self.TextTime, second_toHHMMSS(text))
        else
            if type(text) == 'string' then
                if self.progressingText then
                    self.progressingText.text = text
                end
            elseif text == 1 then
                ---已完成
                self.data.status = Status.FINISHED
                self:FreshStatus(Status.FINISHED)
            end
        end
    end
end

