function TakeoutOrderCellNode:FreshUI(data)
    print('--->>', table.dump(data, false, 2))
    self.data = data
    --self.data.canOrderNum = nil
    self.curNum = nil
    self.isFirst = true
    if self.progressingText then
        self.progressingText.text = ''
    end
    KTool.SetActive(self.OrderNode.gameObject, false)
    local state = checkNumber(data.unlocked) == 1 and data.status ~= Status.Cold
    KTool.SetActive(self.CurrentOrder.gameObject, state)
    KTool.SetActive(self.GetNewOrder.gameObject, checkNumber(data.unlocked) == 1 and data.status == Status.Cold)
    KTool.SetActive(self.BtnGiveup.gameObject, checkNumber(data.unlocked) == 1 and data.status == Status.IDLE)
    self:InitGoodsNodes()
    KTool.SetActive(self.LockOrder.gameObject, checkNumber(data.unlocked) == 0)
    if checkNumber(data.unlocked) == 0 then
        ---如果是未解锁的情况
        local tableFile = SettingMgr:GetInstance():Get(AutoIds.IdSetting3056)
        ---@type TableML.TableFileRow
        local row = tableFile:GetByPrimaryKey(data.id)
        local unlockType = row:Get("unlockType")
        local unlockId = row:Get("unlockId")
        local unlockNum = row:Get("unlockNum")
        local descr = GameUtils.GetUnlockDescr(unlockType, unlockNum, unlockId)
        CfUtils.FillText(self.LockTextDesc, descr)
    else
        local status = checkNumber(data.status)
        if status == Status.Cold then
            CfUtils.FillText(self.TextTime, second_toHHMMSS(self.data.remainTime))
            CfUtils.PlayAnimation(self.AniRoot, "OverseaManageTakeoutCardNode_Cancel")
        else
            ---@type MaidCoffeeTakeOutOrderNpcVo
            local vo = MaidCoffeeUtils.GetMaidCoffeeTakeOutOrderNpcVo(data.npcId)
            if vo then
                CfUtils.FillText(self.TextName.gameObject, vo.name)
                CfUtils.FillText(self.DescriptionText.gameObject, vo.description)
                KTool.SetActive(self.ImgNpcHead.gameObject, true)
                CfUtils.FillImage(self.ImgNpcHead, vo.icon)
            end
            self:FreshStatus(status)
            self:FreshRewards(true)
            self.isFirst = false
        end
    end
end

function TakeoutOrderCellNode:InitGoodsNodes()
    -----@type CommonGoodsList
    for i = 1, self.CommonGoodsList.transform.childCount do
        local go = self.CommonGoodsList.transform:GetChild(i - 1)
        if not isNull(go) then
            KTool.SetActive(go.gameObject,false)
            local effectGo = go.transform:Find("EffectGo")
            if not isNull(effectGo) then
                KTool.SetActive(effectGo.gameObject,false)
            end
        end
    end

    for i = 1, self.Layout.transform.childCount do
        local go = self.Layout.transform:GetChild(i - 1)
        if not isNull(go) then
            KTool.SetActive(go.gameObject,false)
            local effectGo = go.transform:Find("EffectGo")
            if not isNull(effectGo) then
                KTool.SetActive(effectGo.gameObject,false)
            end
        end
    end
end

function TakeoutOrderCellNode:FreshStatus(status)
    KTool.SetActive(self.ReceiveOrders.gameObject, status == Status.IDLE)
    KTool.SetActive(self.DistributeComplete.gameObject, status == Status.FINISHED)
    KTool.SetActive(self.DistributeUnderway.gameObject, status == Status.PROGRESSING)
    KTool.SetActive(self.FontStyleButton.gameObject, status ~= Status.PROGRESSING)
    KTool.SetActive(self.StopReceivingOrders.gameObject, false)

    if status == Status.FINISHED then
        KTool.SetActive(self.ButtonGroup.gameObject, true)
        KTool.SetActive(self.RewardNode.gameObject, true)
        self.fontStyleButtonEnv:ResetFontStyle("B25", localize("领取奖励"))
    elseif status == Status.PROGRESSING then
        if checkInt(self.data.remainTime) >= 0 then
            if self.progressingText then
                self.progressingText.text = second_toHHMMSS(checkInt(self.data.remainTime))
            end
        end
    else
        ---@type MaidCoffeePlayerComponent
        local maidCoffeePlayerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.MaidCoffeePlayerComponent)
        local isToMax = maidCoffeePlayerComponent:IsAreaOrderMax(self.data.area)
        KTool.SetActive(self.StopReceivingOrders.gameObject, isToMax)
        KTool.SetActive(self.RewardNode.gameObject, not isToMax)
        KTool.SetActive(self.ButtonGroup.gameObject, not isToMax)
        if isToMax then
            CfUtils.PlayAnimation(self.AniRoot, "OverseaManageTakeoutCardNode_Stop")
            KTool.SetActive(self.DistributeComplete.gameObject, true)
            KTool.SetActive(self.DeliveryQuantity.gameObject,false)
        else
            self:SetCalculation()
            self:FreshCooks(true)
            local isCan = self:IsCanQuick()
            local isShowQuick = status == Status.IDLE and isCan
            KTool.SetActive(self.DeliveryQuantity.gameObject,isShowQuick)
            CfUtils.PlayAnimation(self.AniRoot, "OverseaManageTakeoutCardNode_Get")
            self:FreshBtnState()
            --订单名称
            ---@type MaidCoffeeTakeOutOrderVo
            local takeOutOrderVo = MaidCoffeeUtils.GetMaidCoffeeTakeOutOrderVo(checkNumber(self.data.orderId))
            if takeOutOrderVo then
                local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(takeOutOrderVo.rewardUpId)
                if goodsVo then
                    CfUtils.FillImage(self.neededGoodIcon, goodsVo.photoPath)
                    CfUtils.FillText(self.neededGoodName, goodsVo.name)
                end
            end
        end
    end
end

function TakeoutOrderCellNode:FreshBtnState()
    self.canOrder = 1
    for i, v in pairs(self.data.cooks) do
        local goodsId = checkNumber(v.cookId)
        local haveNo = GoodsUtils.GetThingNo(goodsId)
        if checkNumber(v.num) * self.curNum > haveNo then
            ----如果存在不足时
            self.canOrder = 0
            break
        end
    end
    if self.canOrder == 1 then
        self.fontStyleButtonEnv:ResetFontStyle("B6", localize("接单"))
        self.FontStyleButton2:GetComponent("FontStyleButton"):ResetFontStyle("B18")
    else
        self.fontStyleButtonEnv:ResetFontStyle("B7", localize("料理制作"))
        self.FontStyleButton2:GetComponent("FontStyleButton"):ResetFontStyle("B6")
    end
    
end

function TakeoutOrderCellNode:IsCanQuick()
    ---@type MaidCoffeePlayerComponent
    local maidCoffeePlayerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.MaidCoffeePlayerComponent)
    local num = maidCoffeePlayerComponent:GetTakeOutAllNum()
    local vo = CfUtils.GetCfVo(AutoIds.IdSetting3033, "MaidCoffeeManagerSettingVo", 51)
    if not isNull(vo) then
        local needNum = checkNumber(vo.num)
        if num >= needNum then
            return true
        end
    end
    return false
end

---FreshCooks
---料理
function TakeoutOrderCellNode:FreshCooks(ignore)
    local t = checkTable(self.data.cooks)
    --KTool.DestroyGameObjectChildren(self.Layout.gameObject, true)
    --构建子节点
    ---@type GoodsConfMgr
    local goodsConfMgr = GoodsConfMgr:GetInstance()
    for i, v in pairs(t) do
        local name = "OrderNode_" .. tostring(i)
        local go = self.Layout.transform:Find(name) --KTool.Instantiate(self.Layout.gameObject, self.OrderNode.gameObject, false)
        if isNull(go) then
            go = KTool.Instantiate(self.Layout.gameObject, self.OrderNode.gameObject, false)
            go.name = name
        end

        KTool.SetActive(go, true)

        if not self.isFirst and not ignore then
            local effectGo = go.transform:Find("EffectGo")  --CS.UnityEngine.GameObject.Instantiate(self.UIFX_GoodRefresh.gameObject)
            if isNull(effectGo) then
                effectGo = CS.UnityEngine.GameObject.Instantiate(self.UIFX_GoodRefresh.gameObject)
                KTool.SetParent(effectGo.gameObject,go.gameObject,false)
                effectGo.name = "EffectGo"
            end
            KTool.SetActive(effectGo.gameObject,true)
        end

        local goodNode = go.transform:Find("GoodNode")
        ---@type GoodNodeMB
        local env = CfUtils.GetLuaScr(goodNode.gameObject, GoodNodeMBPath)
        ----@type GoodsVo
        local vo = goodsConfMgr:GetGoodsVoById(v.cookId)
        if vo then
            env:SetClickButtonAction(function(goodsId, id)
                ----点击出gip
                GameUtils.ShowCommonGoodsTipsBoard(goodNode, vo.id, true)
            end)

            local haveNo = checkNumber(GoodsUtils.GetThingNo(v.cookId))
            local needNo = checkNumber(v.num) * (self.curNum or 1)
            local text = tostring(haveNo)
            if haveNo < needNo then
                text = string.format_color_tag(haveNo, '#d7184a')
            end
            env:Reload({ goodsId = vo.id, isShowNo = true, text = text .. '/' .. needNo, scale = 0.5, id = vo.id })
        end
    end
end

---FreshRewards
---刷新奖励
function TakeoutOrderCellNode:FreshRewards(isIgnore)
    local rewards = checkTable(self.data.rewards)
    --rewardEnv:FreshBaseUI(rewards)
    --KTool.DestroyGameObjectChildren(self.CommonGoodsList.gameObject, false)
    if #rewards > 0 then
        for i, v in pairs(rewards) do
            local name = "GoodNode" .. tostring(i)
            local go = self.CommonGoodsList.transform:Find(name) --KTool.Instantiate(self.Layout.gameObject, self.OrderNode.gameObject, false)
            if isNull(go) then
                go = KTool.Instantiate(self.CommonGoodsList.gameObject, self.GoodNode.gameObject, false)
                go.name = name
            end

            if not self.isFirst and not isIgnore then
                local effectGo = go.transform:Find("EffectGo")  --CS.UnityEngine.GameObject.Instantiate(self.UIFX_GoodRefresh.gameObject)
                if isNull(effectGo) then
                    effectGo = CS.UnityEngine.GameObject.Instantiate(self.UIFX_GoodRefresh.gameObject)
                    effectGo.transform.localScale = Vector3(2, 2, 2)
                    KTool.SetParent(effectGo.gameObject,go.gameObject,false)
                    effectGo.name = "EffectGo"
                end
                KTool.SetActive(effectGo.gameObject,true)
            end


            ---@type GoodNodeMB
            local goEnv = CfUtils.GetLuaScr(go, "Game.Behaviours.GoodNodeMB")
            local goodsId = v.goodsId or v.id
            local num = v.goodsNum or v.num
            --@region 底部title 需要额外添加才会显示
            if not isNull(v.bottomTitle) then
                local txtBottom = go.transform:Find("TxtBottom")
                if txtBottom then
                    CfUtils.FillText(txtBottom, v.bottomTitle)
                end
            end
            --@endregion
            goEnv:SetClickButtonAction(function()
                local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
                if isTable(vo) then
                    GameUtils.ShowCommonTipsBoard(go, vo.name, vo.desc, vo.quality, vo.id, false)
                end
            end)
            KTool.SetActive(go, true)
            goEnv:Reload(
                    {
                        goodsId = goodsId,
                        isShowNo = true, text = 'x' .. FormatCurrencyNum(num) * (self.curNum or 1)
                    }
            )
        end
    end
end

function TakeoutOrderCellNode:OnDestroy()
    Events.RemoveListener(Constants.EventNames.EVENT_CONFIRM_TIME_TICK, self.timeTickEvent)
    self.timeTickEvent = nil
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

function TakeoutOrderCellNode:OnBtnGiveUpClick()
    GameUtils.SecondConfirm(localize("是否拒绝当前订单？"), function()
        GameUtils.Request(Interfaces.MaidCoffeeTakeOutReject, { orderId = self.data.id }, function(request, response)
            if checkNumber(response.errCode) == 0 then
                local _data = response.data.order
                _data.id = self.data.id
                Events.Broadcast(Constants.EventNames.EVENT_TAKEOUT_POPUP_FINISHED, { data = _data })
            end
        end)
    end, function()

    end, localize("获取下一个新订单，需等待_num_", { _num_ = CfUtils.GetTimeHMS(checkNumber(MaidCoffeeUtils.GetMaidCoffeeManagerSettingVo(44).num)) }))
end

function TakeoutOrderCellNode:OnBtnExplainClick()
    GameUtils.ShowCommonTipsBoardAttribute(self.BtnExplain, localize("配送份数"), localize("每多配送1份外卖，需扣除对应的外卖次数"), true, true,nil,true)
end

function TakeoutOrderCellNode:SetCalculation()
    ---@type MaidCoffeePlayerComponent
    local maidCoffeePlayerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.MaidCoffeePlayerComponent)
    if self.calculationEvn then
        local maxNum = maidCoffeePlayerComponent:GetAreaTakeOutLeaveTime(self.data.area)
        local canMakeNum = maxNum --self:GetCanMakeNum()
        maxNum = self:IsCanQuick() and canMakeNum or 1
        if not isNull(self.data.canOrderNum) then
            if self.data.canOrderNum > maxNum then
                self.curNum = maxNum
                self.data.canOrderNum = self.curNum
            else
                self.curNum = self.data.canOrderNum
            end
            self.calculationEvn:SetParams(Bind(self,self.OnCalculationClick),self.data.canOrderNum, 1 , maxNum, localize("当前已达最大份数"))
        else
            local isCanQuick = self:IsCanQuick()
            self.curNum = isCanQuick and maxNum or 1
            self.data.canOrderNum = self.curNum
            self.calculationEvn:SetParams(Bind(self,self.OnCalculationClick),maxNum, 1 , maxNum, localize("当前已达最大份数"))
        end
    end
end

function TakeoutOrderCellNode:GetCanMakeNum()
    if not self:IsCanQuick() then
        return 1
    end
    local canMakeNum
    for i, v in pairs(self.data.cooks) do
        local haveNum = GoodsUtils.GetThingNo(v.cookId)
        local canMakeSign = math.floor(haveNum/v.num)
        if not isNull(canMakeNum) then
            if canMakeNum > canMakeSign then
                canMakeNum = canMakeSign
            end
        else
            canMakeNum = canMakeSign
        end
    end
    return not isNull(canMakeNum) and canMakeNum or 0
end

function TakeoutOrderCellNode:OnCalculationClick(num)
    if self.curNum == num and not self.isFirst then
        return
    end
    self.curNum = num
    self.data.canOrderNum = self.curNum
    self:InitGoodsNodes()
    self:FreshCooks()
    self:FreshBtnState()
    self:FreshRewards()
    if not isNull(self.calculationCallBack) then
        self.calculationCallBack()
    end
    self.isFirst = false
end

return TakeoutOrderCellNode